    },
    {
      "claim": "We must treat AI deployment as a matter of product liability, framing 'black box' models as inherently defective for high-stakes decision-making.",
      "targets": []
    }
  ],
  "key_assumptions": [
    {
      "assumption": "Human cognitive capacity degrades when individuals stop performing the underlying analytical work of a task.",
      "if_wrong": "If humans retain their critical faculties regardless of automation, then 'black box' efficiency gains are net positive without the need for forced transparency."
    },
    {
      "assumption": "The 'jagged' nature of AI intelligence makes unpredictable, high-consequence errors inevitable in opaque systems.",
